package models

import (
	"time"
)

type BarcodePaymentStatus string

const (
	BarcodePaymentStatusPending   BarcodePaymentStatus = "pending"
	BarcodePaymentStatusPaid      BarcodePaymentStatus = "paid"
	BarcodePaymentStatusCancelled BarcodePaymentStatus = "cancelled"
	BarcodePaymentStatusExpired   BarcodePaymentStatus = "expired"
)

type BarcodeTransactionStatus string

const (
	BarcodeTransactionStatusCompleted BarcodeTransactionStatus = "completed"
	BarcodeTransactionStatusFailed    BarcodeTransactionStatus = "failed"
)

// BarcodePayment represents a payment barcode generated by a user
type BarcodePayment struct {
	ID          string               `json:"id" gorm:"primaryKey;type:uuid;default:gen_random_uuid()"`
	UserID      string               `json:"user_id" gorm:"type:uuid;not null;index"`
	Username    string               `json:"username" gorm:"size:100;not null"`
	FullName    string               `json:"full_name" gorm:"size:200;not null"`
	BarcodeCode string               `json:"barcode_code" gorm:"size:100;uniqueIndex;not null"` // Unique code for the barcode
	Amount      float64              `json:"amount" gorm:"type:decimal(20,2);not null"`
	Currency    string               `json:"currency" gorm:"size:10;not null;default:'NGN'"`
	Description string               `json:"description" gorm:"type:text"`
	Status      BarcodePaymentStatus `json:"status" gorm:"size:20;not null;default:'pending'"`
	CreatedAt   time.Time            `json:"created_at" gorm:"autoCreateTime;index"`
	ExpiresAt   time.Time            `json:"expires_at" gorm:"not null;index"`
	PaidAt      *time.Time           `json:"paid_at,omitempty"`
	UpdatedAt   time.Time            `json:"updated_at" gorm:"autoUpdateTime"`
}

// BarcodeTransaction represents a completed payment via barcode
type BarcodeTransaction struct {
	ID                string                   `json:"id" gorm:"primaryKey;type:uuid;default:gen_random_uuid()"`
	BarcodeID         string                   `json:"barcode_id" gorm:"type:uuid;not null;index"`
	PayerID           string                   `json:"payer_id" gorm:"type:uuid;not null;index"`
	PayerUsername     string                   `json:"payer_username" gorm:"size:100;not null"`
	PayerName         string                   `json:"payer_name" gorm:"size:200;not null"`
	RecipientID       string                   `json:"recipient_id" gorm:"type:uuid;not null;index"`
	RecipientUsername string                   `json:"recipient_username" gorm:"size:100;not null"`
	RecipientName     string                   `json:"recipient_name" gorm:"size:200;not null"`
	Amount            float64                  `json:"amount" gorm:"type:decimal(20,2);not null"`
	Currency          string                   `json:"currency" gorm:"size:10;not null"`
	Description       string                   `json:"description" gorm:"type:text"`
	ReferenceNumber   string                   `json:"reference_number" gorm:"size:100;uniqueIndex;not null"`
	Status            BarcodeTransactionStatus `json:"status" gorm:"size:20;not null;default:'completed'"`
	CreatedAt         time.Time                `json:"created_at" gorm:"autoCreateTime;index"`

	// Relations
	Barcode *BarcodePayment `json:"barcode,omitempty" gorm:"foreignKey:BarcodeID"`
}

// TableName specifies the table name for BarcodePayment
func (BarcodePayment) TableName() string {
	return "barcode_payments"
}

// TableName specifies the table name for BarcodeTransaction
func (BarcodeTransaction) TableName() string {
	return "barcode_transactions"
}
